INSERT INTO `principal_message` VALUES
(270013,'JENIFFER GACHAGO ','Chief Principal - Kigumo Technical Training Institute','<p>On behalf of the Kigumo Technical and Vocational College Council, Management, and the entire KTVC fraternity, I welcome you to this institution.</p>\r\n\r\n<p>We are a TVETA-accredited public TVET institution located in Muthithi Town, Murang\'a County, committed to equipping learners with practical, industry-relevant skills for the 21st-century workforce.</p>\r\n\r\n<p>I also welcome you to our website platform, designed to keep you informed about programmes, admissions, news, and events at the College.</p>\r\n\r\n<p>At Kigumo TVC, we believe in \"Skills for Self-Reliance.\" I invite you to explore our website and discover the opportunities awaiting you.</p>\r\n\r\n<p>Karibuni Sana!</p>','https://res.cloudinary.com/dabo8y2bw/image/upload/v1780916462/kigumo-tvc/principal/lxx2e2ay8nuxs7nxdx8f.jpg',1,4,'2026-06-26 19:59:47'),
(270014,'JENIFFER GACHAGO ','Chief Principal - Kigumo Technical','<p>On behalf of the Kigumo Technical and Vocational College Council, Management, and the entire KTVC fraternity, I welcome you to this institution.</p>\r\n\r\n<p>We are a TVETA-accredited public TVET institution located in Muthithi Town, Murang\'a County, committed to equipping learners with practical, industry-relevant skills for the 21st-century workforce.</p>\r\n\r\n<p>I also welcome you to our website platform, designed to keep you informed about programmes, admissions, news, and events at the College.</p>\r\n\r\n<p>At Kigumo TVC, we believe in \"Skills for Self-Reliance.\" I invite you to explore our website and discover the opportunities awaiting you.</p>\r\n\r\n<p>Karibuni Sana!</p>','https://res.cloudinary.com/dabo8y2bw/image/upload/v1780916462/kigumo-tvc/principal/lxx2e2ay8nuxs7nxdx8f.jpg',1,4,'2026-06-26 20:00:03');
